class Solution {
public:
    vector<int> runningSum(vector<int>& a) {
        vector<int> out(a.size());
        int run = 0;
        for (int i = 0; i < (int)a.size(); i++) {
            run += a[i];
            out[i] = run;
        }
        return out;
    }
};
```

