class Solution {
public:
    int pivotIndex(vector<int>& a) {
        int total = 0;
        for (int x : a) total += x;
        int left = 0;
        for (int i = 0; i < (int)a.size(); i++) {
            if (left == total - left - a[i]) return i;
            left += a[i];
        }
        return -1;
    }
};
